#!/usr/bin/env python3
"""Generate native moving-momentum Metal arithmetic from GLSL."""
import argparse
import re
from generate_tke_msl import ROOT, translate


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    path = ROOT / "metal/include/compute/metal/shaders/terrain/moving_momentum_msl.hpp"
    source = translate("moving_momentum", "terrain").replace(
        "Generated by scripts/dev/shaders/generate_tke_msl.py",
        "Generated by scripts/dev/shaders/generate_moving_momentum_msl.py",
    ).replace("using vec2 = float2;", "using vec2 = float2;\nusing ivec3 = int3;")
    source = re.sub(r"lessThan\(cell,\s*begin\)", "cell < begin", source)
    source = re.sub(r"greaterThanEqual\(cell,\s*end\)", "cell >= end", source)
    if args.check:
        if not path.exists() or path.read_text() != source:
            raise SystemExit("moving-momentum Metal source is stale")
    else:
        path.write_text(source)


if __name__ == "__main__":
    main()
